export type Arg =
  | { kind: 'number'; value: number; token: Token }
  | { kind: 'param'; name: string; token: Token };

export interface CommandStatement {
  kind: 'command';
  op: Op;
  token: Token;
  arg?: Arg;
  color?: string;
}

export interface RepeatStatement {
  kind: 'repeat';
  token: Token;
  count: Arg;
  body: Statement[];
}

export interface CallStatement {
  kind: 'call';
  token: Token;
  procedure: Procedure;
  args: Arg[];
}

export type Statement = CommandStatement | RepeatStatement | CallStatement;

export interface Procedure {
  name: string;
  /** The `oto` keyword. */
  token: Token;
  params: string[];
  body: Statement[];
  calls: CallStatement[];
}

export interface Program {
  procedures: Map<string, Procedure>;
  main: Statement[];
}

interface Scope {
  params: ReadonlySet<string>;
  procedure: Procedure | null;
  /** Number of enclosing brackets. */
  depth: number;
}

interface Header {
  keyword: Token;
  nameToken: Token;
  name: string;
  params: string[];
  /** Index of the first token after the header line. */
  end: number;
}

export function parseProgram(source: string, mode: Mode): Program {
  return new Parser(tokenize(source), mode).parse();
