  try {
    const canvas = document.createElement('canvas');
    if (canvas.getContext('webgl2') || canvas.getContext('webgl')) return null;
    return 'ta przeglądarka nie udostępnia WebGL';
  } catch {
    return 'nie udało się sprawdzić obsługi WebGL';
  }
}
