// Static server with no rewrite rules: serves /Logomocja/builds/x/ from /work/dist.
const root = '/work/dist';
const prefix = '/Logomocja/builds/x/';
Bun.serve({
  port: 4173,
  async fetch(req) {
    const { pathname } = new URL(req.url);
    if (!pathname.startsWith(prefix)) return new Response('nie znaleziono', { status: 404 });
    let rel = pathname.slice(prefix.length);
    if (rel === '') rel = 'index.html';
    const file = Bun.file(`${root}/${rel}`);
    return (await file.exists()) ? new Response(file) : new Response('nie znaleziono', { status: 404 });
  },
});
console.log('listening');
EOF
