const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const problems = [];
page.on('pageerror', (e) => problems.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') problems.push('console: ' + m.text()); });
await page.goto(base, { waitUntil: 'networkidle' });
const status = () => page.textContent('#status');
console.log('version', await page.evaluate(() => window.logomocja.version));
console.log('api run', JSON.stringify(await page.evaluate(() => window.logomocja.run('powtorz 4 [np 10 pw 90]', '2d')).then(r => r.segments.length)));

await page.click('#run');
console.log('run ->', await status());
await page.click('#reset');
await page.click('#step');
console.log('step ->', await status());
await page.click('#play');
await page.waitForTimeout(1500);
console.log('play ->', await status(), '| button:', await page.textContent('#play'));
await page.screenshot({ path: '/tmp/pwtest/2d.png' });

// Error handling
await page.fill('#source', 'powtorz 4 [np 10\npw 90');
await page.waitForTimeout(400);
console.log('diag ->', await page.textContent('#diagnostic'), await page.isHidden('#diagnostic'));
await page.click('#run');
console.log('run error ->', await status());

// Editing while paused
await page.fill('#source', 'powtorz 3 [np 20 pw 120]');
await page.waitForTimeout(400);
console.log('diag after fix ->', await page.isHidden('#diagnostic'));
await page.click('#run');
console.log('run fixed ->', await status());

// Persistence across reload (also tests refresh on sub-path)
await page.fill('#source', 'kolor "#d9482b"\npowtorz 5 [np 100 pw 144]');
await page.waitForTimeout(500);
await page.reload({ waitUntil: 'networkidle' });
console.log('after reload source ->', JSON.stringify(await page.inputValue('#source')));

// 3D
await page.click('#mode-3d');
await page.waitForTimeout(1500);
console.log('3d canvas count', await page.locator('#space canvas').count(), 'plane hidden', await page.isHidden('#plane'), 'notice hidden', await page.isHidden('#stage-notice'));
await page.selectOption('#example-select', 'wieza');
await page.click('#example-load');
await page.waitForTimeout(300);
await page.click('#run');
await page.waitForTimeout(500);
console.log('3d run ->', await status());
await page.click('#fit');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/pwtest/3d.png' });

// Mode persisted; reload keeps 3d
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(800);
console.log('mode after reload pressed3d=', await page.getAttribute('#mode-3d', 'aria-pressed'));

console.log('PROBLEMS:', JSON.stringify(problems, null, 1));
await browser.close();
EOF
